<?php
fscanf(STDIN, "%d %d %d %d", $a, $b, $c, $l);

$totalWays = 0;
for ($i = 0; $i <= $l; $i++) {
    $remaining = $l - $i;
    $totalWays += ($remaining + 1) * ($remaining + 2) / 2;
}

$arr = [$a, $b, $c];
$badWays = 0;
for ($idx = 0; $idx < 3; $idx++) {
    $x = $arr[$idx];
    $y = $arr[($idx + 1) % 3];
    $z = $arr[($idx + 2) % 3];

    if ($x > $y + $z) {
        $initialDiff = $x - ($y + $z);
        $maxExtraOnX = $l;

        $startK = $initialDiff;
        if ($startK > $maxExtraOnX) continue;

        $n = $maxExtraOnX - $startK + 1;
        $firstTerm = $l - $startK + 1;
        $lastTerm = $l - $maxExtraOnX + 1;
        // Sum of (l - k + 1) * (l - k + 2) / 2 for k from startK to maxExtraOnX
        // Let m = l - k. m goes from l - startK down to l - maxExtraOnX.
        // Sum = sum_{m = M_min}^{M_max} (m+1)(m+2)/2
        // M_max = l - startK, M_min = l - maxExtraOnX
        $M_max = $l - $startK;
        $M_min = $l - $maxExtraOnX;
        if ($M_max < $M_min) continue; // Should not happen if startK <= maxExtraOnX

        // Sum_{m=A}^{B} (m+1)(m+2)/2 where A = M_min, B = M_max
        // = 1/2 * Sum (m^2 + 3m + 2)
        // Sum m^2 from A to B = S2(B) - S2(A-1)
        // Sum m from A to B = S1(B) - S1(A-1)
        // Sum 1 = B - A + 1

        $A = $M_min;
        $B = $M_max;

        function S1($n) { return $n >= 0 ? $n * ($n + 1) / 2 : 0; }
        function S2($n) { return $n >= 0 ? $n * ($n + 1) * (2 * $n + 1) / 6 : 0; }

        $sum_m2 = S2($B) - S2($A - 1);
        $sum_m = S1($B) - S1($A - 1);
        $sum_1 = $B - $A + 1;

        $badWays += ($sum_m2 + 3 * $sum_m + 2 * $sum_1) / 2;
    } else {
        // x <= y + z
        // We need k_x > k_y + k_z + (y + z - x)
        // Let d = y + z - x >= 0
        // k_x >= k_y + k_z + d + 1
        // k_x + k_y + k_z <= l
        // => 2(k_y + k_z) + d + 1 <= l
        // => k_y + k_z <= (l - d - 1) / 2
        // Also k_x can be from (k_y + k_z + d + 1) to (l - k_y - k_z)
        // Number of ways for fixed s = k_y + k_z:
        // ways_yz = s + 1
        // ways_x = (l - s) - (s + d + 1) + 1 = l - 2s - d
        // Sum over s = 0 to floor((l - d - 1)/2)

        $d = $y + $z - $x;
        $maxS = ($l - $d - 1) >> 1; // floor division

        if ($maxS >= 0) {
            // Sum_{s=0}^{maxS} (s+1) * (l - d - 2s)
            // = (l-d) * Sum(s+1) - 2 * Sum(s(s+1))
            // Sum_{s=0}^{N} (s+1) = (N+1)(N+2)/2 = S1(N+1)
            // Sum_{s=0}^{N} s(s+1) = Sum(s^2 + s) = S2(N) + S1(N) = N(N+1)(N+2)/3

            $N = $maxS;
            $term1 = ($l - $d) * ($N + 1) * ($N + 2) / 2;
            $term2 = 2 * $N * ($N + 1) * ($N + 2) / 3;
            $badWays += $term1 - $term2;
        }
    }
}

echo $totalWays - $badWays . "\n";
